"""Compare full-width storage entries with independent generated byte vectors."""

import random
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from tests.harness import Case, ensure
from vos import toolenv

ROOT = Path(__file__).resolve().parents[2]


def _bytes(data: bytes) -> str:
    return "{" + ",".join(str(value) for value in data) + "}"


def typed_entries() -> None:
    compiler = shutil.which("cc") or shutil.which("gcc") or shutil.which("clang")
    ensure(compiler is not None, "typed entry checks require a native C compiler")
    if compiler is None:
        raise RuntimeError("no native C compiler")
    rng = random.Random(0x10_005)  # noqa: S311 - reproducible public test vectors
    tuples = {tuple(rng.getrandbits(64) for _ in range(6)) for _ in range(128)}
    for field in range(6):
        for edge in (0, 1, 255, 256, 1 << 32, (1 << 64) - 1):
            key = [0] * 6
            key[field] = edge
            tuples.add(tuple(key))
    rows = []
    for key in sorted(tuples):
        fields = "{" + ",".join(f"UINT64_C({value})" for value in key) + "}"
        encoded = b"".join(value.to_bytes(8, "big") for value in key)
        rows.append("{" + fields + "," + _bytes(encoded) + "}")
    vectors = "static const struct key_vector keys[] = {" + ",\n".join(rows) + "};\n"
    rows = []
    for _ in range(64):
        words = (rng.getrandbits(64), rng.getrandbits(64), rng.getrandbits(24), rng.getrandbits(64))
        domain, kind = rng.randrange(128), rng.randrange(2)
        tag, digest = rng.randbytes(16), rng.randbytes(32)
        encoded = (b"VOSEXT01" + b"".join(value.to_bytes(8, "little") for value in words)
                   + domain.to_bytes(4, "little") + kind.to_bytes(4, "little") + tag + digest)
        fields = ",".join(f"UINT64_C({value})" for value in words)
        extent = "{" + fields + f",{domain},{kind}," + _bytes(tag) + "," + _bytes(digest) + "}"
        rows.append("{" + extent + "," + _bytes(encoded) + "}")
    vectors += "static const struct extent_vector extents[] = {" + ",\n".join(rows) + "};\n"
    work = toolenv.environment(ROOT, sys.platform).parent / "typed-entry-tests"
    work.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="typed-", dir=work) as directory:
        scratch = Path(directory)
        (scratch / "typed_entry_vectors.h").write_text(vectors, encoding="utf-8", newline="\n")
        binary = scratch / "typed-entry"
        result = subprocess.run([
            compiler, "-std=c17", "-O2", "-Wall", "-Wextra", "-Werror", "-Wstrict-prototypes",
            "-pedantic", "-I" + str(ROOT / "storage/include"), "-I" + str(scratch),
            str(ROOT / "storage/src/typed_entry.c"), str(ROOT / "storage/host/typed_entry.c"),
            "-o", str(binary)
        ], capture_output=True, text=True, timeout=60, check=False)
        ensure(result.returncode == 0, f"typed entry compilation failed: {result.stderr}")
        if result.returncode != 0:
            raise RuntimeError(result.stderr)
        result = subprocess.run([str(binary)], capture_output=True, text=True, timeout=60, check=False)
        ensure(result.returncode == 0, result.stderr or result.stdout)
        ensure("typed entry: ok" in result.stdout, "typed entry verdict missing")


def cases() -> list[Case]:
    return [Case("typed keys preserve tuple order and extents retain complete authentication metadata",
                 typed_entries, lane="guest")]
